/* KGN V20 - size-specific prices and distinct size-wise wholesale enquiry lines, read-only cloud. */
(()=>{'use strict';
const $=id=>document.getElementById(id);
if(!document.querySelector('link[data-kgn-pack-style]')){const l=document.createElement('link');l.rel='stylesheet';l.href='./bundle.css?v=20';l.dataset.kgnPackStyle='';document.head.append(l)}
const GROUP3=new Set(['0-0','16-18','20-20','20-24','26-30','32-34','32-36','38-40']);
const GROUP6=new Set(['20-30','22-32']);const GROUP5=new Set(['32-40','28-32']);const GROUPXL=new Set(['XL','XXL','XXXL','4XL']);
const LABEL={hi:{title:'अपना थोक बंडल चुनें',size:'साइज़ चुनें',pack:'बंडल प्रकार चुनें',qty:'पीस चुनें',add:'इन्क्वायरी में जोड़ें',close:'बंद करें',missing:'साइज़, बंडल और मात्रा चुनें',stock:'स्टॉक और उपलब्ध साइज़ की पुष्टि करें',pieces:'पीस',empty:'इन्क्वायरी खाली है'},en:{title:'Choose wholesale bundle',size:'Choose size',pack:'Choose bundle type',qty:'Choose pieces',add:'Add to enquiry',close:'Close',missing:'Choose size, bundle and quantity',stock:'Please confirm stock and sizes',pieces:'pieces',empty:'Your enquiry is empty'},ur:{title:'ہول سیل بنڈل منتخب کریں',size:'سائز منتخب کریں',pack:'بنڈل منتخب کریں',qty:'پیس منتخب کریں',add:'انکوائری میں شامل کریں',close:'بند کریں',missing:'سائز، بنڈل اور مقدار منتخب کریں',stock:'اسٹاک اور سائز کی تصدیق کریں',pieces:'پیس',empty:'انکوائری خالی ہے'}};
const trl=()=>LABEL[document.documentElement.lang]||LABEL.hi;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='kgn_v19_size_bundle_lines';let optionsReady=false,lines=[];try{const old=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(old))lines=old.filter(x=>x&&typeof x.id==='string'&&typeof x.size==='string'&&[3,4,5,6].includes(x.pack)&&Number.isInteger(x.pieces)&&x.pieces>=3&&Number.isInteger(x.bundles)&&x.bundles>0).slice(0,100)}catch{}
const packTypes=p=>{let a=Array.isArray(p.packOptions)&&p.packOptions.length?p.packOptions.map(Number):[Number(p.moq)||6];return [...new Set(a.filter(n=>[3,4,5,6].includes(n)))].sort((a,b)=>a-b)};
const sizes=p=>Array.isArray(p.sizeOptions)?p.sizeOptions:[];
const priceFor=(p,size)=>{const r=p?.sizeRates?.[size];return typeof r==='number'&&Number.isFinite(r)&&r>=0?r:null};
function allowedTypes(p,size){const a=packTypes(p);if(GROUP6.has(size))return a.filter(n=>n===6);if(GROUP5.has(size))return a.filter(n=>n===5);if(GROUP3.has(size))return a.filter(n=>n===3||n===6);if(GROUPXL.has(size))return a.filter(n=>n===3||n===4||n===6);return a}
function allowedPieces(size,pack){if(!pack)return[];if(GROUP6.has(size))return pack===6?[6]:[];if(GROUP5.has(size))return pack===5?[5]:[];if(GROUP3.has(size))return pack===3?[3]:pack===6?[3,6]:[];if(GROUPXL.has(size))return pack===3?[3]:pack===4?[4]:pack===6?[3,6]:[];return[pack]}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(lines))}catch{};cart={};for(const x of lines)cart[x.id]=(cart[x.id]||0)+x.bundles;storeSet('kgn_v11_cart',JSON.stringify(cart))}
const dlg=document.createElement('dialog');dlg.id='kgnBundleDialog';dlg.className='kgn-bundle-dialog';dlg.innerHTML='<div class="kgn-dialog-head"><strong id="kgnBundleHeading"></strong><button class="kgn-dialog-close" type="button" id="kgnBundleClose" aria-label="Close">×</button></div><div class="kgn-dialog-content" id="kgnBundleContent"></div>';let item=null,chosenSize='',chosenPack=0,chosenPieces=0;
function paint(){if(!item)return;const t=trl(),ss=sizes(item),pk=chosenSize?allowedTypes(item,chosenSize):[],qty=allowedPieces(chosenSize,chosenPack);if(!pk.includes(chosenPack)){chosenPack=0;chosenPieces=0}if(!qty.includes(chosenPieces))chosenPieces=0;const actualQty=allowedPieces(chosenSize,chosenPack);$('kgnBundleHeading').textContent=t.title;$('kgnBundleClose').setAttribute('aria-label',t.close);$('kgnBundleContent').innerHTML=`<h3>${esc(displayName(item))}</h3><div class="kgn-option-title">📏 ${t.size}</div><div class="kgn-chip-grid">${ss.map(s=>`<button type="button" data-kgn-size="${esc(s)}" class="kgn-chip ${s===chosenSize?'selected':''}" aria-pressed="${s===chosenSize}">${esc(s)}</button>`).join('')||`<small>${t.stock}</small>`}</div><div class="kgn-option-title">📦 ${t.pack}</div><div class="kgn-chip-grid">${pk.map(n=>`<button type="button" data-kgn-pack="${n}" class="kgn-chip ${n===chosenPack?'selected':''}" aria-pressed="${n===chosenPack}">${n} ${t.pieces}</button>`).join('')||`<small>${t.stock}</small>`}</div><p class="kgn-help"><strong>💰 ${chosenSize?(priceFor(item,chosenSize)===null?'Rate on enquiry':money(priceFor(item,chosenSize))+' / '+tr('units')[item.unit]):'पहले Size चुनें'}</strong></p><div class="kgn-option-title">${t.qty}</div><div class="kgn-chip-grid">${actualQty.map(n=>`<button type="button" data-kgn-pieces="${n}" class="kgn-chip ${n===chosenPieces?'selected':''}" aria-pressed="${n===chosenPieces}">${n} ${t.pieces}</button>`).join('')}</div><p class="kgn-help">${t.stock}. 20-30 / 22-32: 6 ${t.pieces}; 28-32 / 32-40: 5 ${t.pieces}.</p><button type="button" id="kgnBundleConfirm" class="kgn-dialog-primary">${t.add}</button>`}
function open(p){if(!optionsReady){alert('Sizes और Rates लोड हो रहे हैं। कृपया कुछ देर बाद फिर खोलें।');return;}item=p;chosenSize='';chosenPack=0;chosenPieces=0;paint();dlg.showModal()}
function add(){if(!optionsReady)return;if(!item||!chosenSize||!chosenPack||!allowedPieces(chosenSize,chosenPack).includes(chosenPieces)){alert(trl().missing);return}const line=lines.find(x=>x.id===item.id&&x.size===chosenSize&&x.pack===chosenPack&&x.pieces===chosenPieces);if(line)line.bundles=Math.min(999,line.bundles+1);else lines.push({id:item.id,size:chosenSize,pack:chosenPack,pieces:chosenPieces,bundles:1});persist();renderAll();dlg.close();toast(tr('added'))}
function decorate(){document.querySelectorAll('.product-card').forEach(card=>{let add=card.querySelector('[data-add]');if(!add)return;const p=products.find(x=>x.id===add.dataset.add);if(!p)return;let div=card.querySelector('.kgn-pack-readout');if(!div){div=document.createElement('div');div.className='kgn-pack-readout';add.before(div)}div.textContent='📏 '+(sizes(p).join(', ')||trl().stock)+' · 📦 '+packTypes(p).join(' / ')+' '+trl().pieces;const pr=card.querySelector('.price-row');if(pr){const rr=sizes(p).map(z=>priceFor(p,z)).filter(z=>z!==null);pr.innerHTML=rr.length?`<strong>${money(Math.min(...rr))}${Math.min(...rr)===Math.max(...rr)?'':'+'}</strong><span class="unit">/piece · size-wise</span>`:'<span class="ask">Size-wise rate on enquiry</span>'}})}
function newCart(){const t=trl();if(!optionsReady){$('cartCount').hidden=!lines.length;$('cartCount').textContent=lines.length;$('selectedCount').textContent='Rates loading…';$('enquiryForm').hidden=true;$('cartItems').innerHTML='<div class="empty">Loading sizes and rates… Please wait.</div>';return;}lines=lines.filter(x=>{const p=products.find(z=>z.id===x.id);return p&&sizes(p).includes(x.size)&&allowedTypes(p,x.size).includes(x.pack)&&allowedPieces(x.size,x.pack).includes(x.pieces)});persist();const count=lines.reduce((n,x)=>n+x.bundles,0),pieces=lines.reduce((n,x)=>n+x.pieces*x.bundles,0);$('cartCount').hidden=!count;$('cartCount').textContent=count;$('selectedCount').textContent=pieces+' '+t.pieces;$('enquiryForm').hidden=!count;$('cartItems').innerHTML=count?lines.map((x,i)=>{const p=products.find(z=>z.id===x.id);return `<div class="kgn-cart-line"><img src="${esc(imgSrc(p.image))}" alt=""><div class="kgn-cart-info"><strong>${esc(displayName(p))}</strong><small>📏 ${esc(x.size)} · 💰 ${priceFor(p,x.size)===null?'Rate on enquiry':money(priceFor(p,x.size))+'/piece'}</small><small>📦 ${x.pack} ${t.pieces} → ${x.pieces} ${t.pieces} × ${x.bundles} = ${x.pieces*x.bundles} ${t.pieces}</small><small>💵 ${priceFor(p,x.size)===null?'Total on enquiry':money(priceFor(p,x.size)*x.pieces*x.bundles)+' total'}</small><div class="kgn-qty"><button type="button" data-kgn-qty="${i}" data-d="-1" aria-label="Decrease">−</button><b>${x.bundles}</b><button type="button" data-kgn-qty="${i}" data-d="1" aria-label="Increase">+</button></div></div></div>`}).join(''):`<div class="empty">${t.empty}</div>`;decorate()}
function message(){const t=trl(),l=document.documentElement.lang;const out=l==='en'?['Hello K.G.N. Fashion Zone,','Wholesale enquiry:']:l==='ur'?['السلام علیکم K.G.N. Fashion Zone،','ہول سیل انکوائری:']:['नमस्ते K.G.N. Fashion Zone,','थोक कपड़ों की इन्क्वायरी:'];if($('buyerName').value.trim())out.push(tr('buyer')+': '+$('buyerName').value.trim());if($('buyerCity').value.trim())out.push(tr('city')+': '+$('buyerCity').value.trim());for(const x of lines){const p=products.find(z=>z.id===x.id);if(!p)continue;const rate=priceFor(p,x.size);out.push('• '+displayName(p)+(p.sku?' ['+p.sku+']':'')+' | 📏 '+x.size+' | 📦 '+x.pack+' '+t.pieces+' → '+x.pieces+' '+t.pieces+' × '+x.bundles+' = '+x.pieces*x.bundles+' '+t.pieces+(rate!==null?' | '+money(rate)+'/piece | Total: '+money(rate*x.pieces*x.bundles):' | Rate on enquiry'))}out.push(t.stock+'. '+tr('notOrder'));return out.join('\n')}
async function syncOptions(){if(!cloudConfigured||!sb)return;const {data,error}=await sb.from('products').select('id,size_options,pack_options,size_rates').eq('published',true).limit(250);if(error){console.warn('KGN V19 needs migrated bundle columns',error);setStatus('Bundle columns missing; check Supabase SQL.','error');return}const byId=new Map((data||[]).map(x=>[x.id,x]));for(const p of products){const row=byId.get(p.id);p.sizeOptions=Array.isArray(row?.size_options)?row.size_options:[];
p.packOptions=Array.isArray(row?.pack_options)?row.pack_options:[];p.sizeRates=row?.size_rates&&typeof row.size_rates==='object'&&!Array.isArray(row.size_rates)?row.size_rates:{}}optionsReady=true;renderAll()}

function install(){document.body.append(dlg);$('kgnBundleClose').onclick=()=>dlg.close();dlg.addEventListener('click',e=>{if(e.target===dlg){dlg.close();return}const s=e.target.closest('[data-kgn-size]');if(s){chosenSize=s.dataset.kgnSize;chosenPack=0;chosenPieces=0;paint();return}const p=e.target.closest('[data-kgn-pack]');if(p){chosenPack=Number(p.dataset.kgnPack);chosenPieces=0;paint();return}const n=e.target.closest('[data-kgn-pieces]');if(n){chosenPieces=Number(n.dataset.kgnPieces);paint();return}if(e.target.id==='kgnBundleConfirm')add()});window.renderCart=newCart;window.makeMessage=message;const old=window.refreshCloud;window.refreshCloud=async function(){optionsReady=false;await old();await syncOptions()};document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){e.preventDefault();e.stopImmediatePropagation();const p=products.find(x=>x.id===add.dataset.add);if(p)open(p);return}const b=e.target.closest('[data-kgn-qty]');if(b){e.preventDefault();e.stopImmediatePropagation();const i=Number(b.dataset.kgnQty),x=lines[i];if(!x)return;x.bundles+=Number(b.dataset.d);if(x.bundles<=0)lines.splice(i,1);persist();renderAll()}},true);const orig=window.renderCards;window.renderCards=function(host,arr){orig(host,arr);decorate()};setTimeout(syncOptions,1100)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();

